      try {
        const errorBody = await response.json() as { message?: string };
        if (errorBody.message) {
          errorMsg = errorBody.message;
        }
      } catch {
        // Ignore parse error
      }
      throw new Error(errorMsg);
    }
    return response.json() as Promise<T>;
  }

