{"file_path": "retry_utils.py", "content": "import time
from functools import wraps
from typing import Callable, TypeVar, Any

T = TypeVar('T')

def retry_with_backoff(max_retries: int = 3, base_delay: float = 0.5) -> Callable[[Callable[..., T]], Callable[..., T]]:
    """Retry a function with exponential backoff on any exception.

    Args:
        max_retries: Maximum number of retries after the initial call.
        base_delay: Base delay in seconds for first retry.

    Returns:
        Decorated function that retries on failure.
    """
    def decorator(func: Callable[..., T]) -> Callable[..., T]:
        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> T:
            attempt = 0
            while True:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt >= max_retries:
                        raise e
                    delay = base_delay * (2 ** attempt)
                    time.sleep(delay)
                    attempt += 1
        return wrapper
    return decorator

def test_retry_success() -> None:
    """Test that a function that fails twice then succeeds is retried correctly."""
    calls = 0

    @retry_with_backoff(max_retries=3, base_delay=0.01)
    def flaky_network_call() -> str:
        nonlocal calls
        calls += 1
        if calls < 3:
            raise ConnectionError(f"Simulated failure, attempt {calls}")
        return "success"

    result = flaky_network_call()
    assert result == "success"
    assert calls == 3, f"Expected 3 calls, got {calls}"
    print("test_retry_success passed")

if __name__ == '__main__':
    test_retry_success()
"}

