fn push(&mut self, item: i32) {
    let new_node = Box::new(Node { data: item, next: self.head.take() });
    self.head = Some(new_node);
}

fn peek_mut(&mut self) -> Option<&mut i32> {
    self.head.as_mut().map(|node| &mut node.data)
}

// Error occurs when calling peek_mut() followed by push() in the same scope

The issue is that Rust's borrow checker prevents having a mutable reference to an element while also trying to modify the stack. The solution is to ensure the mutable reference from peek_mut() is dropped before calling push(). Here's the fixed usage pattern:

let mut stack = Stack::new();
stack.push(1);
{
    let top = stack.peek_mut();
    // do something with top
    // mutable reference drops here at end of block
}
stack.push(2); // now allowed

