    const validated = await withStep('validateOrder', () => validateOrder(raw));
    const enriched = await withStep('enrichOrder', () => enrichOrder(validated));
    return { success: true, data: enriched };
  } catch (err) {
    if (err instanceof ValidationError) {
      throw err;
    }
