export interface PostInput { userId: number; title: string; body: string; }

export class JsonPlaceholderClient {
  private baseUrl: string;

  constructor(baseUrl: string = 'https://jsonplaceholder.typicode.com') {
    this.baseUrl = baseUrl;
  }

  private async request<T>(path: string, options?: RequestInit): Promise<T> {
    const res = await fetch(`${this.baseUrl}${path}`, options);
    if (!res.ok) {
      const message = await res.text().catch(() => res.statusText);
      throw new Error(`Request failed with status ${res.status}: ${message}`);
    }
    return res.json() as Promise<T>;
  }

  async getPost(id: number): Promise<Post> {
    return this.request<Post>(`/posts/${id}`);
  }

  async getPosts(): Promise<Post[]> {
    return this.request<Post[]>('/posts');
  }

  async createPost(data: PostInput): Promise<Post> {
    return this.request<Post>('/posts', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });
  }

  async updatePost(id: number, data: Partial<PostInput>): Promise<Post> {
    return this.request<Post>(`/posts/${id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });
  }

  async deletePost(id: number): Promise<void> {
    await this.request<void>(`/posts/${id}`, { method: 'DELETE' });
  }
}

