func FetchWeather(city string) (*Weather, error) {
    url := fmt.Sprintf("https://api.weather.com/v1/current?city=%s", city)
    client := &http.Client{Timeout: 5 * time.Second}
    resp, err := client.Get(url)
    if err != nil {
        return nil, err
