import os

class TempDir:
    def __init__(self, prefix='tmp', suffix='', base_dir=None, keep=False):
        self.prefix = prefix
        self.suffix = suffix
        self.base_dir = base_dir
        self.keep = keep
        self.path = None

    def __enter__(self):
        self.path = tempfile.mkdtemp(prefix=self.prefix, suffix=self.suffix, dir=self.base_dir)
        return self.path

    def __exit__(self, exc_type, exc_val, exc_tb):
        if not self.keep and self.path and os.path.exists(self.path):
            shutil.rmtree(self.path, ignore_errors=True)
        return False
"}

