import csv

def compute_stats(file_path, delimiter=','):
    stats = {}
    with open(file_path, 'r', newline='') as f:
        reader = csv.DictReader(f, delimiter=delimiter)
        rows = list(reader)
        if not rows:
            return stats
        columns = rows[0].keys()
        for col in columns:
            values = []
            for row in rows:
                val = row.get(col)
                if val is None or val == '':
                    continue
                try:
                    values.append(float(val))
                except ValueError:
                    continue
            if values:
                stats[col] = {
                    'count': len(values),
                    'mean': sum(values) / len(values),
                    'min': min(values),
                    'max': max(values)
                }
    return stats
