```python
import sys
import pandas as pd
import json

def main():
    if len(sys.argv) != 2:
        print("Usage: python validate.py <csv_path>", file=sys.stderr)
        sys.exit(1)
    file_path = sys.argv[1]
    try:
        df = pd.read_csv(file_path)
    except Exception as e:
        print(f"Error reading file: {e}", file=sys.stderr)
        sys.exit(1)

    checks = []
    overall = "PASS"

    # Check 1: No null CustomerID
    if 'CustomerID' in df.columns:
        null_count = df['CustomerID'].isnull().sum()
        if null_count == 0:
            checks.append({"check": "CustomerID not null", "status": "PASS"})
        else:
            checks.append({"check": "CustomerID not null", "status": "FAIL", "message": f"{null_count} nulls found"})
            overall = "FAIL"
    else:
        checks.append({"check": "CustomerID not null", "status": "FAIL", "message": "Column missing"})
        overall = "FAIL"

    # Check 2: TotalPrice non-negative
    if 'TotalPrice' in df.columns:
        neg_count = (df['TotalPrice'] < 0).sum()
        if neg_count == 0:
            checks.append({"check": "TotalPrice non-negative", "status": "PASS"})
        else:
            checks.append({"check": "TotalPrice non-negative", "status": "FAIL", "message": f"{neg_count} negative values"})
            overall = "FAIL"
    else:
        checks.append({"check": "TotalPrice non-negative", "status": "FAIL", "message": "Column missing"})
        overall = "FAIL"

    # Check 3: Date format
    if 'Date' in df.columns:
        try:
            pd.to_datetime(df['Date'], errors='raise')
            checks.append({"check": "Date is datetime", "status": "PASS"})
        except Exception as e:
            checks.append({"check": "Date is datetime", "status": "FAIL", "message": str(e)})
            overall = "FAIL"
    else:
        checks.append({"check": "Date is datetime", "status": "FAIL", "message": "Column missing"})
        overall = "FAIL"

    result = {"checks": checks, "overall": overall}
    print(json.dumps(result, indent=2))
    if overall == "FAIL":
        sys.exit(1)

if __name__ == "__main__":
    main()
```

