from flask import Flask, request, jsonify
import requests

app = Flask(__name__)

NLP_ENDPOINT = "https://api.dialogflow.com/v1/query?v=20150910"
API_KEY = "YOUR_API_KEY"

@app.route("/webhook", methods=["POST"])
def webhook():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({"error": "Invalid JSON"}), 400

    session_id = data.get("session_id")
    message = data.get("message")
    user_id = data.get("user_id", "")

    if not session_id or not message:
        return jsonify({"error": "Missing required fields"}), 400

    if not isinstance(session_id, str):
        return jsonify({"error": "session_id must be a string"}), 422

    headers = {"Authorization": f"Bearer {API_KEY}", "Content-Type": "application/json"}
    payload = {
        "query": message,
        "sessionId": session_id,
        "contexts": [],
        "lang": "en",
    }

    try:
        response = requests.post(NLP_ENDPOINT, json=payload, headers=headers, timeout=5)
        response.raise_for_status()
        nlp_data = response.json()
        reply = nlp_data["result"]["fulfillment"]["speech"]
        return jsonify({"reply": reply, "session_id": session_id})
    except requests.exceptions.Timeout:
        return jsonify({"error": "NLP service timeout"}), 502
    except requests.exceptions.RequestException as e:
        return jsonify({"error": f"NLP service error: {str(e)}"}), 502

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
"}

